      "evidence": "Fundamental warranties must sit outside the general regime"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve claims for fraud, wilful misconduct, concealment and inaccurate/misleading disclosure"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "No deemed disclosure merely because a document was present, discoverable, or in public records."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete deemed Buyer knowledge and universal non-reliance/exclusive-remedy wording."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make receipt of an unconditional written consent, and satisfaction/waiver of all associated conditions, a Buyer-benefit CP."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "No Completion with company debt or security remaining."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Seller bears all bonuses and related on-costs, whether paid before or after Completion."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "A $180,000 payment indemnity does not address the commercial IP risk."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity, outside the general cap/basket/time bar, for all incident-related loss, regulatory action, notifications, remediation and third-party claims."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Treat non-ordinary, prepaid, non-cancellable or Completion-triggered liabilities appropriately in the purchase-price/working-capital mechanism or require Seller settlement/termination before Completion."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Separate fundamental, tax and specific-indemnity regimes from the 20% cap, basket and 18-month period"
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "retain a robust title warranty, a 100%-of-price title cap, longer survival, PPSR searches/releases"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Require a stand-alone tax covenant/indemnity for all pre-Completion tax liabilities"
    }
  ],
